\set ON_ERROR_STOP on
begin;
create schema test_helpers;
create table test_helpers.context(key text primary key,id uuid);
grant usage on schema test_helpers to anon,authenticated,service_role;
grant select,insert,update on test_helpers.context to anon,authenticated,service_role;
create function test_helpers.ok(passed boolean, label text) returns void language plpgsql as $$
begin if passed is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function test_helpers.throws(statement text, code text, label text) returns void language plpgsql as $$
declare got text;
begin
 begin execute statement; exception when others then get stacked diagnostics got=returned_sqlstate; end;
 if got is distinct from code then raise exception 'FAIL: % expected %, got %',label,code,coalesce(got,'success'); end if;
 raise notice 'PASS: %',label;
end $$;
grant execute on all functions in schema test_helpers to anon,authenticated,service_role;
